self.SourcesTestRunner=self.SourcesTestRunner||{},SourcesTestRunner.replaceInSource=function(e,t,n){e.textEditor.setReadOnly(!1);for(let o=0;o<e.textEditor.linesCount;++o){const i=e.textEditor.line(o).indexOf(t);if(-1===i)continue;const r=new TextUtils.TextRange(o,i,o,i+t.length);e.textEditor.editRange(r,n);break}},SourcesTestRunner.commitSource=function(e){e.commitEditing()},SourcesTestRunner.undoSourceEditing=function(e){e.textEditor.undo()};